def transform(grid):
    from collections import deque

    out = [row[:] for row in grid]
    R, C = len(grid), len(grid[0])

    # Find connected components of nonzero cells other than the 5-line markers.
    seen = set()
    components = []
    for r in range(R):
        for c in range(C):
            if grid[r][c] == 0 or grid[r][c] == 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for nx, ny in ((x-1, y), (x+1, y), (x, y-1), (x, y+1)):
                    if (0 <= nx < R and 0 <= ny < C and
                        grid[nx][ny] not in (0, 5) and (nx, ny) not in seen):
                        seen.add((nx, ny))
                        q.append((nx, ny))
            components.append(comp)

    # Find maximal straight runs of 5s.
    lines = []
    for r in range(R):
        c = 0
        while c < C:
            if grid[r][c] != 5:
                c += 1
                continue
            start = c
            while c < C and grid[r][c] == 5:
                c += 1
            if c - start >= 2:
                lines.append(("h", r, start, c - 1))

    for c in range(C):
        r = 0
        while r < R:
            if grid[r][c] != 5:
                r += 1
                continue
            start = r
            while r < R and grid[r][c] == 5:
                r += 1
            if r - start >= 2:
                lines.append(("v", c, start, r - 1))

    for orient, fixed, lo, hi in lines:
        for comp in components:
            cells = set(comp)
            contacts = []
            for r, c in comp:
                for nr, nc in ((r-1, c), (r+1, c), (r, c-1), (r, c+1)):
                    if orient == "h" and nr == fixed and lo <= nc <= hi:
                        contacts.append((r, c))
                    elif orient == "v" and nc == fixed and lo <= nr <= hi:
                        contacts.append((r, c))
            if not contacts:
                continue

            rmin = min(r for r, c in comp)
            rmax = max(r for r, c in comp)
            cmin = min(c for r, c in comp)
            cmax = max(c for r, c in comp)

            if orient == "h":
                # The attached vertical pattern is copied along the 5-run.
                source_col = contacts[0][1]
                for r in range(rmin, rmax + 1):
                    color = grid[r][source_col]
                    if color:
                        for c in range(lo, hi + 1):
                            out[r][c] = color
            else:
                # Repeat the attached pattern block along the vertical 5-run.
                height = rmax - rmin + 1
                for r in range(lo, hi + 1):
                    source_r = rmin + ((r - rmin) % height)
                    for c in range(cmin, cmax + 1):
                        color = grid[source_r][c]
                        if color:
                            out[r][c] = color

    return out
